sys_script.script:
// BR9: Manager Limited Write
// Managers NOT working a case can only modify assigned_to, assignment_group, state.
(function () {
    // Only applies to users with manager role
    if (!gs.hasRole('x_2241073_securi_0.manager')) return;
    // Skip if user is admin
    if (gs.hasRole('admin')) return;

    // Check if manager is "working" the case
    var userId = gs.getUserID();
    if (current.getValue('assigned_to') == userId) return;
    if (current.getValue('opened_by') == userId) return;

    // Check assignment_group membership
    var grpId = current.getValue('assignment_group');
    if (grpId) {
        var grp = new GlideRecord('sys_user_grmember');
        grp.addQuery('group', grpId);
        grp.addQuery('user', userId);
        grp.query();
        if (grp.hasNext()) return;
    }

    // Check Case Team membership
    var ct = new GlideRecord('x_2241073_securi_0_case_team');
    ct.addQuery('case_id', current.getUniqueValue());
    ct.addQuery('user_id', userId);
    ct.query();
    if (ct.hasNext()) return;

    // Manager is NOT working the case — revert changes to restricted fields
    var restrictedFields = [
        'category', 'subcategory', 'torq_incident_id', 'torq_incident_url',
        'case_type', 'case_source', 'detection_source', 'severity',
        'affected_systems', 'affected_users', 'investigation_summary',
        'containment_actions', 'remediation_actions', 'root_cause',
        'lessons_learned', 'caller_id', 'short_description', 'description', 'priority'
    ];

    for (var i = 0; i < restrictedFields.length; i++) {
        var field = restrictedFields[i];
        if (current.getValue(field) != previous.getValue(field)) {
            current.setValue(field, previous.getValue(field));
        }
    }
})();
